import importlib
import uuid

import pytest

import bedrock_protocol
from bedrock_protocol import v2193 as proto

# generated by gophertunnel b8bd735:
# packet.Header{PacketID: 2, SenderSubClient: 1, TargetSubClient: 2} then
# packet.PlayStatus{Status: packet.PlayStatusPlayerSpawn}
FRAMED_PLAY_STATUS = bytes.fromhex("824800000003")

PLAY_STATUS = proto.PlayStatusPacket(status=proto.PlayStatus.PLAYER_SPAWN)


def test_the_bare_names_are_the_latest_protocol():
    latest = importlib.import_module(f"bedrock_protocol.v{bedrock_protocol.LATEST_PROTOCOL}")
    assert bedrock_protocol.TextPacket is latest.TextPacket


def test_the_bare_protocol_number_is_the_latest_protocol():
    assert bedrock_protocol.PROTOCOL == bedrock_protocol.LATEST_PROTOCOL


def test_the_bare_codec_round_trips_a_packet():
    packet = bedrock_protocol.PlayStatusPacket(status=bedrock_protocol.PlayStatus.PLAYER_SPAWN)
    assert bedrock_protocol.decode(packet.ID, bedrock_protocol.encode(packet)) == packet


def test_the_header_packs_recipient_then_sender_as_bds_does():
    assert proto.encode_packet(PLAY_STATUS, recipient_sub_id=1, sender_sub_id=2) == FRAMED_PLAY_STATUS


def test_the_header_unpacks_recipient_then_sender_as_bds_does():
    header, _ = proto.decode_packet(FRAMED_PLAY_STATUS)
    assert (header.packet_id, header.recipient_sub_id, header.sender_sub_id) == (PLAY_STATUS.ID, 1, 2)


def test_a_framed_packet_decodes_to_its_body():
    _, packet = proto.decode_packet(FRAMED_PLAY_STATUS)
    assert packet == PLAY_STATUS


def test_positionals_fill_fields_in_order_and_keywords_by_name():
    assert proto.Vec3(1, 2, z=3) == proto.Vec3(x=1, y=2, z=3)


def test_a_positional_and_a_keyword_for_one_field_are_rejected():
    with pytest.raises(TypeError, match="multiple values"):
        proto.Vec3(1, x=2)


def test_a_keyword_the_schema_does_not_name_is_rejected():
    with pytest.raises(TypeError, match="no field 'w'"):
        proto.Vec3(w=1)


def test_more_positionals_than_fields_are_rejected():
    with pytest.raises(TypeError, match="at most 3"):
        proto.Vec3(1, 2, 3, 4)


def test_a_struct_field_is_a_live_reference():
    packet = proto.MovePlayerPacket()
    pos = packet.pos
    packet.pos.x = 5.5
    assert pos.x == 5.5


def test_a_list_field_is_a_copy():
    packet = proto.PlayerAuthInputPacket(input_data=[proto.PlayerAuthInputPacket.InputData.UP])
    packet.input_data.append(proto.PlayerAuthInputPacket.InputData.DOWN)
    assert packet.input_data == [proto.PlayerAuthInputPacket.InputData.UP]


@pytest.fixture
def unnamed_status():
    return proto.PlayStatusPacket.from_bytes(bytes([0, 0, 0, 0xFF]))


def test_a_value_the_schema_does_not_name_crosses_as_an_int(unnamed_status):
    assert type(unnamed_status.status) is int
    assert unnamed_status.status == 255


def test_a_value_the_schema_does_not_name_shows_in_the_repr(unnamed_status):
    assert "status=255" in repr(unnamed_status)


def test_a_value_the_schema_does_not_name_encodes_again(unnamed_status):
    assert bytes(unnamed_status) == bytes([0, 0, 0, 0xFF])


def test_a_container_id_the_schema_does_not_name_round_trips():
    window = proto.ContainerClosePacket(container_id=5)
    assert proto.ContainerClosePacket.from_bytes(bytes(window)) == window


def test_a_named_value_assigned_to_an_int_field_comes_back_as_the_enum_member():
    window = proto.ContainerClosePacket(container_id=5)
    window.container_id = proto.ContainerID.INVENTORY
    assert window.container_id is proto.ContainerID.INVENTORY


def test_a_value_that_does_not_fit_the_enum_is_rejected():
    with pytest.raises(TypeError, match="does not fit the enum"):
        proto.ContainerClosePacket(container_id=1000)


def test_a_string_carries_any_bytes():
    packet = proto.LevelChunkPacket(serialized_chunk=bytes([0xFF, 0x00, 0xC3, 0x41]))
    assert packet.serialized_chunk.encode("utf-8", "surrogateescape") == bytes([0xFF, 0x00, 0xC3, 0x41])


def test_a_string_carrying_any_bytes_round_trips():
    packet = proto.LevelChunkPacket(serialized_chunk=bytes([0xFF, 0x00, 0xC3, 0x41]))
    assert proto.LevelChunkPacket.from_bytes(bytes(packet)) == packet


def test_a_string_can_be_assigned_text():
    packet = proto.LevelChunkPacket()
    packet.serialized_chunk = "héllo"
    assert packet.serialized_chunk == "héllo"


def test_a_uuid_crosses_as_uuid():
    value = uuid.UUID("12345678-9abc-def0-1122-334455667788")
    request = proto.CommandRequestPacket().origin
    request.uuid = value
    assert request.uuid == value
    assert type(request).from_bytes(bytes(request)).uuid == value


def test_a_python_keyword_member_keeps_the_dsl_underscore():
    assert "pass_" in proto.BiomeConsolidatedFeatureData.__match_args__


def test_decode_rejects_trailing_bytes():
    with pytest.raises(ValueError, match="trailing bytes"):
        proto.decode(PLAY_STATUS.ID, bytes(PLAY_STATUS) + b"\x00")


def test_decode_rejects_a_truncated_body():
    with pytest.raises(ValueError, match="at byte"):
        proto.decode(PLAY_STATUS.ID, bytes(PLAY_STATUS)[:-1])


def test_decode_rejects_an_unknown_packet_id():
    with pytest.raises(KeyError, match="no packet 1023"):
        proto.decode(1023, b"")


@pytest.mark.parametrize(
    ("packet_id", "cls"), proto.PACKETS.items(), ids=lambda value: getattr(value, "__name__", str(value))
)
def test_every_packet_class_is_registered_under_its_id(packet_id, cls):
    assert packet_id == cls.ID
